// Presmium's mascot: a black Bombay kitten in silhouette. Each action is a few drawn key poses with a timeline of how
// many ticks each one holds, like a hand-drawn sprite; the sheets and timelines are generated by
// tools/mascot/build.ts. `mascotFrame` is a pure function of the time, so a film can seek it; `mountMascot` plays it
// in an element on the page's clock. The black cat shows on light backgrounds and a white one on dark.
import catSheet from './mascot/cat.png'
import whiteCatSheet from './mascot/cat-light.png'
import { SHEET } from './mascot/sheet.ts'

export type MascotAction = keyof typeof SHEET.actions

export const MASCOT_ACTIONS = Object.keys(SHEET.actions) as MascotAction[]

// Imported as modules: a bundler gives each sheet its address (Vite a file URL, the Studio client a data URL).
const SHEETS = { light: catSheet, dark: whiteCatSheet }

/** The pose shown at `ms` into an action, its column and row on the sheet, and how far (in frame widths) the cat
 * has moved forward since the action began, for a host that carries it across the page. */
export function mascotFrame(action: MascotAction, ms: number): { column: number, row: number, travel: number } {
  const { row, timeline } = SHEET.actions[action] as { row: number, timeline: readonly (readonly number[])[] }
  const total = timeline.reduce((sum, [, ticks = 0]) => sum + ticks, 0)
  const perLoop = timeline.reduce((sum, [, ticks = 0, move = 0]) => sum + ticks * move, 0)
  const ticks = Math.max(0, Math.floor(ms / SHEET.tickMs))
  let n = ticks % total, travel = Math.floor(ticks / total) * perLoop
  for (const [column = 0, length = 0, move = 0] of timeline) {
    if (n < length) return { column, row, travel: (travel + n * move) * SHEET.unit / SHEET.frame[0] }
    n -= length; travel += length * move
  }
  return { column: 0, row, travel: 0 }
}

/** Shows one frame of the sheet in `el`; the `pm-ui-mascot` class sizes it and picks the sheet for the theme. */
function show(el: HTMLElement, column: number, row: number) {
  el.style.setProperty('--pm-mascot-x', `${column / (SHEET.columns - 1) * 100}%`)
  el.style.setProperty('--pm-mascot-y', `${row / (SHEET.rows - 1) * 100}%`)
}

/**
 * Plays the mascot in `el` until stopped; `set` changes the action, starting it from its beginning. Under reduced
 * motion it shows the first pose of each action and stays still.
 */
export function mountMascot(el: HTMLElement, action: MascotAction = 'idle') {
  el.classList.add('pm-ui-mascot')
  el.setAttribute('aria-hidden', 'true')
  el.style.setProperty('--pm-mascot-sheet', `url("${SHEETS.light}")`)
  el.style.setProperty('--pm-mascot-sheet-dark', `url("${SHEETS.dark}")`)
  el.style.setProperty('--pm-mascot-columns', String(SHEET.columns))
  el.style.setProperty('--pm-mascot-rows', String(SHEET.rows))
  const still = typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches
  let current = action, start = performance.now(), frame = 0, shown = ''
  const tick = (now: number) => {
    const { column, row } = mascotFrame(current, still ? 0 : now - start)
    const key = `${column}:${row}`
    if (key !== shown) { show(el, column, row); shown = key }
    if (!still) frame = requestAnimationFrame(tick)
  }
  tick(start)
  return {
    set(next: MascotAction) {
      if (next === current) return
      current = next; start = performance.now()
      if (still) tick(start)
    },
    stop() { cancelAnimationFrame(frame) },
  }
}
